p = "/work/model.scad"
s = open(p).read()
# 1. part selector annotation must be on the SAME line as the assignment
s = s.replace('part = "box";\n// [box, lid, pin, assembly]', 'part = "box"; // [box, lid, pin, assembly]')
assert s.count('part = "box"; // [box, lid, pin, assembly]') == 1

# 2. box back wall: widen axial clearance slots to >= 0.5 per side
old = '''            // top band of back wall split into segs clearing lid knuckles axially (0.4 gap each side)
            translate([-40, -30, 27.0]) cube([11.88, 2.4, 3.0]);
            translate([-17.52, -30, 27.0]) cube([11.28, 2.4, 3.0]);
            translate([6.64, -30, 27.0]) cube([11.28, 2.4, 3.0]);
            translate([28.12, -30, 27.0]) cube([11.88, 2.4, 3.0]);'''
assert s.count(old) == 1
new = '''            // top band of back wall split into segs clearing lid knuckles axially (0.5 gap each side)
            translate([-40, -30, 27.0]) cube([11.68, 2.4, 3.0]);
            translate([-17.42, -30, 27.0]) cube([11.08, 2.4, 3.0]);
            translate([6.74, -30, 27.0]) cube([11.08, 2.4, 3.0]);
            translate([28.32, -30, 27.0]) cube([11.68, 2.4, 3.0]);'''
s = s.replace(old, new)

# 3. lid back skirt: widen axial clearance slots to >= 0.5 per side
old = '''            translate([-40, -30, 3]) cube([9.6, 2.4, 7.6]);
            translate([-5.44, -30, 3]) cube([10.88, 2.4, 7.6]);
            translate([18.72, -30, 3]) cube([10.88, 2.4, 7.6]);
            translate([30.4, -30, 3]) cube([9.6, 2.4, 7.6]);'''
assert s.count(old) == 1
new = '''            translate([-40, -30, 3]) cube([9.4, 2.4, 7.6]);
            translate([-5.34, -30, 3]) cube([10.68, 2.4, 7.6]);
            translate([18.82, -30, 3]) cube([10.68, 2.4, 7.6]);
            translate([30.6, -30, 3]) cube([9.4, 2.4, 7.6]);'''
s = s.replace(old, new)

# 4. box lug webs: narrow in X with 0.5 clearance to neighbouring lid knuckle faces
old = '''            translate([k0x0, -31, 26.8]) cube([k0x1-k0x0, 3.4, 4.0]);
            translate([k2x0, -31, 26.8]) cube([k2x1-k2x0, 3.4, 4.0]);
            translate([k4x0, -31, 26.8]) cube([k4x1-k4x0, 3.4, 4.0]);'''
assert s.count(old) == 1
new = '''            translate([k0x0 + 0.5, -31, 26.8]) cube([k0x1-k0x0 - 1.0, 3.4, 4.0]);
            translate([k2x0 + 0.5, -31, 26.8]) cube([k2x1-k2x0 - 1.0, 3.4, 4.0]);
            translate([k4x0 + 0.5, -31, 26.8]) cube([k4x1-k4x0 - 1.0, 3.4, 4.0]);'''
s = s.replace(old, new)

# 5. lid lug webs: narrow in X with 0.5 clearance to neighbouring box knuckle faces
old = '''            translate([k1x0, -31, 0]) cube([k1x1-k1x0, 3.4, 5]);
            translate([k3x0, -31, 0]) cube([k3x1-k3x0, 3.4, 5]);'''
assert s.count(old) == 1
new = '''            translate([k1x0 + 0.5, -31, 0]) cube([k1x1-k1x0 - 1.0, 3.4, 5]);
            translate([k3x0 + 0.5, -31, 0]) cube([k3x1-k3x0 - 1.0, 3.4, 5]);'''
s = s.replace(old, new)

# 6. knuckle cylinders: shorten boxes by 0.5/0.5 axial, bore still cuts through
s = s.replace('xcyl(k0x0, k0x1, Rkn, yh, zh);', 'xcyl(k0x0 + 0.5, k0x1 - 0.5, Rkn, yh, zh);')
s = s.replace('xcyl(k2x0, k2x1, Rkn, yh, zh);', 'xcyl(k2x0 + 0.5, k2x1 - 0.5, Rkn, yh, zh);')
s = s.replace('xcyl(k4x0, k4x1, Rkn, yh, zh);', 'xcyl(k4x0 + 0.5, k4x1 - 0.5, Rkn, yh, zh);')
s = s.replace('xcyl(k1x0, k1x1, Rkn, yh, lid_zh);', 'xcyl(k1x0 + 0.5, k1x1 - 0.5, Rkn, yh, lid_zh);')
s = s.replace('xcyl(k3x0, k3x1, Rkn, yh, lid_zh);', 'xcyl(k3x0 + 0.5, k3x1 - 0.5, Rkn, yh, lid_zh);')

# 7. pin: thinner shaft + shorter heads for radial clearance
old = '''        xcyl(-32.4, 32.4, rpin, 0, 3);
        xcyl(30.4, 32.4, 3, 0, 3);
        xcyl(-32.4, -30.4, 3, 0, 3);'''
assert s.count(old) == 1
new = '''        xcyl(-32.4, 32.4, 1.8, 0, 3);
        xcyl(31.4, 32.4, 2.8, 0, 3);
        xcyl(-32.4, -31.4, 2.8, 0, 3);'''
s = s.replace(old, new)
s = s.replace('[\"shaft\", \"thickness\", [0, 3, 3], [0, -1, 0], 3.8]', '[\"shaft\", \"thickness\", [0, 3, 3], [0, -1, 0], 3.6]')
s = s.replace('[[30.4, -3, 0], [32.4, 3, 6]]', '[[31.4, -2.8, 0], [32.4, 2.8, 6]]')

# 8. lid spec: declare the individual-print overhang zones
old = '''        ["overhangs_allowed", [
            ["hinge knuckles and bores print in place", [[-18.2, -33.9, 0.0], [18.2, -27.1, 4.2]]],
            ["lid top bridging over plug cavity", [[-37.2, -24.9, 10.1], [37.2, 25.2, 11.1]]]
        ]],'''
assert s.count(old) == 1
new = '''        ["overhangs_allowed", [
            ["hinge knuckles and bores print in place", [[-18.2, -33.9, 0.0], [18.2, -27.1, 4.2]]],
            ["lid top bridging over plug cavity", [[-37.2, -24.9, 10.1], [37.2, 25.2, 11.1]]],
            ["lid skirt bottom band, flat 0.4-gap bridge when assembled", [[-40.2, -30.2, 2.8], [40.2, 30.2, 3.2]]],
            ["lid skirt inner ledge over box rim, flat bridge", [[-37.8, -30.2, 10.4], [37.8, 27.8, 10.8]]],
            ["hinge knuckle underside rounds, 0.4-gap print bridge", [[-18.2, -33.9, 3.0], [18.2, -27.1, 6.6]]],
            ["lid back skirt gaps between knuckles, flat bridge", [[-30.6, -30.2, 2.8], [30.6, -27.4, 3.4]]],
            ["notch top face over notch void, tiny bridge", [[-3.5, 26.3, 1.8], [3.5, 28.0, 2.2]]]
        ]],'''
s = s.replace(old, new)
open(p, "w").write(s)
